package dev.industrialtechnology.space;
import java.util.List;import net.minecraft.item.*;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.entity.*;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.world.World;import net.minecraftforge.common.util.EnumHelper;import dev.industrialtechnology.core.ModRegistry;
public final class ItemSpaceSuit extends ItemArmor {
    @cpw.mods.fml.relauncher.SideOnly(cpw.mods.fml.relauncher.Side.CLIENT)private dev.industrialtechnology.client.space.SpaceSuitModel model;
    @cpw.mods.fml.relauncher.SideOnly(cpw.mods.fml.relauncher.Side.CLIENT)@Override public net.minecraft.client.model.ModelBiped getArmorModel(EntityLivingBase e,ItemStack s,int slot){if(model==null)model=new dev.industrialtechnology.client.space.SpaceSuitModel(tier,armorType);return model.configure(e,slot);}
    public static final ArmorMaterial SUIT=EnumHelper.addArmorMaterial("INDUSTRIAL_SPACE",33,new int[]{2,6,5,2},5);public final int tier;
    public ItemSpaceSuit(int tier,int slot){super(SUIT,0,slot);this.tier=tier;setUnlocalizedName("industrialtech.spacesuit_"+(tier+1)+"_"+slot);setTextureName("industrialtech:spacesuit_"+(tier+1)+"_"+slot);setCreativeTab(ModRegistry.TAB);setMaxDamage(450+tier*450);}
    public static int capacity(ItemStack s){return s!=null&&s.getItem() instanceof ItemSpaceSuit&&((ItemSpaceSuit)s.getItem()).armorType==1?SpaceConfig.suitMinutes[((ItemSpaceSuit)s.getItem()).tier]*1200:0;}
    public static int air(ItemStack s){return s!=null&&s.hasTagCompound()?Math.max(0,Math.min(capacity(s),s.getTagCompound().getInteger("BreathingTicks"))):0;}
    public static void setAir(ItemStack s,int ticks){if(capacity(s)<=0)return;if(!s.hasTagCompound())s.setTagCompound(new NBTTagCompound());s.getTagCompound().setInteger("BreathingTicks",Math.max(0,Math.min(capacity(s),ticks)));}
    public static int fullTier(EntityPlayer p){int tier=2;for(int i=0;i<4;i++){ItemStack s=p.inventory.armorInventory[i];if(s==null||!(s.getItem() instanceof ItemSpaceSuit)||((ItemSpaceSuit)s.getItem()).armorType!=3-i||s.getItemDamage()>=s.getMaxDamage())return -1;tier=Math.min(tier,((ItemSpaceSuit)s.getItem()).tier);}return tier;}
    @Override public String getArmorTexture(ItemStack s,Entity e,int slot,String type){return "industrialtech:textures/armor/suit_"+(tier+1)+(slot==2?"_2.png":"_1.png");}
    @Override public void addInformation(ItemStack s,EntityPlayer p,List out,boolean a){out.add("Pressure suit tier "+(tier+1)+"; full 4-piece set required.");if(armorType==1){int t=air(s)/20;out.add("Air: "+t/60+":"+String.format(java.util.Locale.ROOT,"%02d",t%60)+" / "+SpaceConfig.suitMinutes[tier]+" minutes");out.add("Refill with breathable air at the Suit Refill Station.");}out.add(tier==0?"Short EVA; highest thermal wear.":tier==1?"Insulated EVA protection.":"Extended EVA; reinforced thermal layers.");}
}
